"use client";

import Link from 'next/link';
import React from 'react';
import { Button } from './ui/moving-border';
import courseData from "../data/music_course.json";
import { BackgroundGradient } from './ui/background-gradient';

interface Course {
	id: number,
	title: string,
	slug: string,
	description: string,
	price: number,
	instructor: string,
	isFeatured: boolean,
}

function FeaturedCourses() {
	const featuredCourses = courseData.courses.filter((course: Course) => course.isFeatured == true);

  return (
    <div className="py-12 bg-blue-900/5">
			<div className='text-center'>
				<h2 className="text-base text-teal-600 font-semibold tracking-wide uppercase">FEATURED COURSES</h2>
				<p className="mt-2 text-3xl leading-8 font-extrabold tracking-tight text-white sm:text-4xl">Learn With the Best</p>
			</div>
			<div className='mt-[6rem] mx-8'>
				<div className='grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 justify-center'>
					{featuredCourses.map((course: Course) => (
						<div key={course.id} className="flex justify-center">
							<BackgroundGradient className='flex flex-col mx-auto rounded-[22px] bg-white dark:bg-zinc-900 overflow-hidden h-full max-w-sm'>
								<div className="p-4 sm:p-6 flex flex-col items-center text-center grow">
									<p className="text-lg sm:text-xl text-black mt-4 mb-2 dark:text-neutral-200">{course.title}</p>
									<p className="text-sm text-neutral-600 dark:text-neutral-400 grow">{course.description}</p>
									<Link href={`/courses/${course.slug}`}>
										<Button className="cursor-pointer">
											Learn More
										</Button>
									</Link>
								</div>
							</BackgroundGradient>
						</div>
					))}
				</div>
			</div>
			<div className="text-center mt-8">
				<Link href="/courses">
					<Button className="cursor-pointer">
						View All Courses
					</Button>
				</Link>
			</div>
    </div>
	)
}

export default FeaturedCourses